 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            min_r = min(rr for rr, _ in cells)
            min_c = min(cc for _, cc in cells)
            shape = frozenset((rr - min_r, cc - min_c) for rr, cc in cells)
            result.append((color, cells, shape))
    return result


def transform(grid):
    out = [row[:] for row in grid]
    components = _components(grid)
    templates = {}
    for color, cells, shape in components:
        if color != 1:
            templates.setdefault(shape, set()).add(color)
    for color, cells, shape in components:
        if color == 1 and shape in templates:
            replacement = min(templates[shape])
            for r, c in cells:
                out[r][c] = replacement
    return out
